// This file is generated by AI.

// 引擎条目: 显示名、版本解析与"项目实际用哪个引擎"的判定 (纯函数)。
//
// 引擎即 WebGAL 引擎发行包 (解压后是一份可直接运行的静态站点)。它的自述文件
// `webgal-engine.json` 由 WebGAL 构建脚本生成, 因此名称与版本可以直接读它;
// 读不到 (老版本或自建引擎) 就退回目录名, 不编造版本号。

import { findBinding, type ProjectBinding } from './bindings';
import { baseName } from './paths';
import type { EngineEntry, Settings } from './settings';

/** `webgal-engine.json` (或 `package.json`) 里我们关心的字段。 */
export interface EngineManifestInfo {
  name?: string;
  version?: string;
  manifestId?: string;
  /** 图标相对路径 (相对引擎根目录) */
  icon?: string;
}

/**
 * 解析引擎自述文件。
 *
 * 版本优先取 `webgalVersion` (WebGAL 运行时版本, 构建脚本与 `version` 同步写入),
 * 没有时退回 `version` —— 自建引擎的 `package.json` 只有后者。缺省的字段留空,
 * 由调用方决定退回目录名还是显示"未知版本"。
 */
export function parseEngineManifest(raw: unknown): EngineManifestInfo {
  if (!raw || typeof raw !== 'object') return {};
  const record = raw as Record<string, unknown>;
  return {
    name: nonEmptyString(record.name),
    version: nonEmptyString(record.webgalVersion) ?? nonEmptyString(record.version),
    manifestId: nonEmptyString(record.id),
    icon: nonEmptyString(record.icon),
  };
}

/** 自述文件里是否真的提供了可用信息 (空对象视为没读到)。 */
export function hasManifestInfo(info: EngineManifestInfo | null | undefined): boolean {
  return Boolean(info && (info.name || info.version || info.manifestId));
}

function nonEmptyString(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
}

/** 新建引擎条目 (id 只在本机设置里唯一)。 */
export function makeEngineEntry(path: string, info?: EngineManifestInfo, id?: string): EngineEntry {
  return {
    id: id ?? `eng-${Date.now().toString(36)}-${Math.random().toString(16).slice(2, 8)}`,
    name: info?.name?.trim() || baseName(path),
    version: info?.version,
    manifestId: info?.manifestId,
    path,
  };
}

/** 下拉框与列表里的显示名。 */
export function engineLabel(engine: EngineEntry): string {
  return engine.version ? `${engine.name} ${engine.version}` : engine.name;
}

/** 按 id 找引擎。 */
export function findEngine(engines: EngineEntry[], id: string | undefined): EngineEntry | null {
  if (!id) return null;
  return engines.find((engine) => engine.id === id) ?? null;
}

/**
 * 项目实际使用的引擎层。
 *
 * 只有**显式绑定**才算数: 项目内置引擎时 (目录里有 index.html) 预览直接用项目本身,
 * 不含引擎的项目则必须由用户在"项目"页里选一个。刻意不提供"默认引擎"回落 ——
 * 那会让"没选过的项目"看起来像已经选好了, 用户分不清预览到底挂的是哪一份引擎。
 */
export function resolveProjectEngine(
  settings: Pick<Settings, 'engines'>,
  bindings: Record<string, ProjectBinding>,
  projectPath: string | null
): EngineEntry | null {
  if (!projectPath) return null;
  const binding = findBinding(bindings, projectPath);
  return findEngine(settings.engines, binding?.engineId);
}

/** 同上, 但直接给出预览服务器需要的路径。 */
export function resolveProjectEnginePath(
  settings: Pick<Settings, 'engines'>,
  bindings: Record<string, ProjectBinding>,
  projectPath: string | null
): string | undefined {
  return resolveProjectEngine(settings, bindings, projectPath)?.path;
}

/** 校验引擎目录时用到的清单文件名 (按优先级)。 */
export const ENGINE_MANIFEST_FILES = ['webgal-engine.json', 'package.json'] as const;
